import{_ as o,o as e,c as i,ae as a}from"./chunks/framework.Dh1jimFm.js";const h=JSON.parse('{"title":"AutoFingers (CAT tool automation)","description":"","frontmatter":{},"headers":[],"relativePath":"tools/autofingers.md","filePath":"tools/autofingers.md"}'),l={name:"tools/autofingers.md"};function r(s,t,n,u,m,d){return e(),i("div",null,t[0]||(t[0]=[a('<h1 id="autofingers-cat-tool-automation" tabindex="-1">AutoFingers (CAT tool automation) <a class="header-anchor" href="#autofingers-cat-tool-automation" aria-label="Permalink to &quot;AutoFingers (CAT tool automation)&quot;">​</a></h1><p>AutoFingers automates repetitive CAT-tool actions (primarily memoQ) by:</p><ol><li>Reading source → target pairs from a TMX file</li><li>Copying the active source segment</li><li>Looking up the translation</li><li>Pasting the result and optionally confirming the segment</li></ol><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><ul><li><strong>Tools → AutoFingers - CAT Tool Automation...</strong> (<code>Ctrl+Shift+A</code>)</li><li>Or: <strong>Tools</strong> tab → <strong>✋ AutoFingers</strong></li></ul><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><ol><li>Open <strong>✋ AutoFingers</strong>.</li><li>Choose a TMX file (or use <strong>📥 Import from TM</strong>).</li><li>Set your TMX language codes (for example: <code>en</code> → <code>nl</code>).</li><li>Put focus in memoQ on the segment you want to process.</li><li>Use one of the global hotkeys: <ul><li><code>Ctrl+Alt+P</code> — process a single segment</li><li><code>Ctrl+Shift+L</code> — start/stop loop mode</li><li><code>Ctrl+Alt+S</code> — stop loop mode</li><li><code>Ctrl+Alt+R</code> — reload TMX</li></ul></li></ol><h2 id="settings-that-matter" tabindex="-1">Settings that matter <a class="header-anchor" href="#settings-that-matter" aria-label="Permalink to &quot;Settings that matter&quot;">​</a></h2><ul><li><strong>Confirm segments</strong><ul><li>Enabled: confirms segments (Ctrl+Enter)</li><li>Disabled: moves to next without confirming (Alt+N)</li></ul></li><li><strong>Skip no match</strong>: when enabled, AutoFingers will move on if there’s no TMX hit.</li><li><strong>Timing</strong>: increase delays if memoQ or your PC is slow, decrease if you want it faster.</li></ul><h2 id="safety-limitations" tabindex="-1">Safety &amp; limitations <a class="header-anchor" href="#safety-limitations" aria-label="Permalink to &quot;Safety &amp; limitations&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>AutoFingers sends keyboard shortcuts to the active window. Always make sure memoQ is focused before starting loop mode.</p></div><ul><li>Global hotkeys may require running Supervertaler <strong>as Administrator</strong> on some systems.</li><li>Automation is inherently sensitive to UI focus, memoQ shortcuts, and machine performance.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./tmx-editor.html">TMX Editor</a></li></ul>',14)]))}const g=o(l,[["render",r]]);export{h as __pageData,g as default};
